}","title":"Kotlin/Wasm JavaScript interoperability","source":"https://kotlinlang.org/docs/wasm-js-interop.html","sections":["Interoperability with JavaScript > Use JavaScript code in Kotlin > External declarations > JavaScript functions"],"line_start":17,"line_end":33,"score":0.6119625568389893,"release_version":null,"availability":"unknown"},{"anchor":"change-declaration-names","start":2771,"end":3315,"split_code":false,"platforms":["native"],"id":"755003dd3db4d99f0bcf2cc36c52c892db2828929982cadeff06c54ceedd40d0","document_id":"native-objc-interop","strategy":"semantic","text":"Change declaration names

