}

// Usage with the ObjCName annotations
let array = MySwiftArray()
let index = array.index(of: "element")

See another example in the Kotlin-Swift interopedia .","title":"Interoperability with Swift/Objective-C","source":"https://kotlinlang.org/docs/native-objc-interop.html","sections":["Interoperability with Swift/Objective-C > Using Kotlin in Swift/Objective-C > Change declaration names"],"line_start":51,"line_end":65,"score":0.6109238862991333,"release_version":null,"availability":"unknown"}]}

