}","title":"Kotlin/Wasm JavaScript interoperability","source":"https://kotlinlang.org/docs/wasm-js-interop.html","sections":["Interoperability with JavaScript > Use JavaScript code in Kotlin > JavaScript modules"],"line_start":180,"line_end":206,"score":0.5447241067886353,"release_version":null,"availability":"unknown"},{"anchor":"kotlin-functions-with-javascript-code","start":4172,"end":4777,"split_code":false,"platforms":["wasm"],"id":"2a45fdbc2e9b82719f1114692542bffc5123785e8433f8fcf8908031acb3c12a","document_id":"wasm-js-interop","strategy":"semantic","text":"Kotlin functions with JavaScript code

