}","title":"Kotlin/Wasm JavaScript interoperability","source":"https://kotlinlang.org/docs/wasm-js-interop.html","sections":["Interoperability with JavaScript > Use JavaScript code in Kotlin > JavaScript modules"],"line_start":180,"line_end":206,"score":0.537666380405426,"release_version":null,"availability":"unknown"}]}

